/**
 * QuizFramework - AI Model-Generated Quiz Quality Assurance Benchmark (QG-Eval)
 * -----------------------------------------------------------------------------
 * A scientific, automated benchmark designed to evaluate the technical,
 * pedagogical, and psychometric quality of quizzes generated by AI models.
 *
 * Evaluates across 6 core dimensions (0 to 100 points):
 * 1. Structural & Schema Conformance (20 pts)
 * 2. Time Pressure & Minimum Time Calibration (15 pts)
 * 3. Distractor Quality & Option Length Parity (20 pts)
 * 4. Pedagogical Independence & Zero-Errata (20 pts)
 * 5. Explanation Depth & LaTeX Formatting (15 pts)
 * 6. Question Balance & Answer Key Distribution (10 pts)
 *
 * Usage:
 *   node test/quiz-benchmark.js [optional-quiz-file.js|json]
 */

const fs = require("fs");
const path = require("path");

class QuizBenchmark {
  constructor(options = {}) {
    this.options = {
      strictMode: false,
      verbose: true,
      ...options
    };
  }

  /**
   * Parse input as either JSON string or JavaScript sandbox
   */
  parseQuizData(rawContent) {
    let cleaned = rawContent.trim();
    if (cleaned.startsWith("```")) {
      cleaned = cleaned.replace(/^```[a-zA-Z0-9_-]*\n?/, "").replace(/\n?```\s*$/, "").trim();
    }

    try {
      const data = JSON.parse(cleaned);
      if (Array.isArray(data)) {
        return { config: { title: "Untitled Quiz" }, questions: data };
      }
      return data;
    } catch (e) {
      // Try evaluating as JavaScript defining window.QUIZ_CONFIG and window.QUIZ_QUESTIONS
      const sandbox = { window: {} };
      try {
        const fn = new Function("window", cleaned);
        fn(sandbox.window);
        if (sandbox.window.QUIZ_QUESTIONS) {
          return {
            config: sandbox.window.QUIZ_CONFIG || {},
            questions: sandbox.window.QUIZ_QUESTIONS
          };
        }
      } catch (err) {
        throw new Error(`Failed to parse quiz input as JSON or JS: ${err.message}`);
      }
    }
    throw new Error("Unable to extract questions from input.");
  }

  /**
   * Run benchmark on loaded quiz dataset
   */
  evaluate(quizDataset) {
    const config = quizDataset.config || {};
    const questions = quizDataset.questions || [];

    const report = {
      score: 0,
      grade: "F",
      dimensions: {},
      findings: [],
      warnings: [],
      errors: [],
      stats: {
        totalQuestions: questions.length,
        questionTypes: {},
        avgEstimatedTime: 0,
        avgWordsPerQuestion: 0,
        longestOptionBiasRate: 0
      }
    };

    if (!Array.isArray(questions) || questions.length === 0) {
      report.errors.push("Questions dataset is empty or not an array.");
      report.grade = "F";
      return report;
    }

    // 1. Dimension 1: Structural & Schema Conformance (20 pts)
    const dim1 = this.evaluateStructure(config, questions);
    report.dimensions["Structure & Schema"] = dim1;

    // 2. Dimension 2: Time Pressure & Calibration (15 pts)
    const dim2 = this.evaluateTimePressure(config, questions, report.stats);
    report.dimensions["Time Calibration"] = dim2;

    // 3. Dimension 3: Distractor Quality & Option Length Parity (20 pts)
    const dim3 = this.evaluateDistractors(questions, report.stats);
    report.dimensions["Distractor Quality"] = dim3;

    // 4. Dimension 4: Pedagogical Independence & Zero-Errata (20 pts)
    const dim4 = this.evaluatePedagogyAndErrata(questions);
    report.dimensions["Zero-Errata & Independence"] = dim4;

    // 5. Dimension 5: Explanation Depth & Formatting (15 pts)
    const dim5 = this.evaluateExplanationsAndMath(questions);
    report.dimensions["Explanation & LaTeX"] = dim5;

    // 6. Dimension 6: Balance & Answer Distribution (10 pts)
    const dim6 = this.evaluateBalanceAndDistribution(questions, report.stats);
    report.dimensions["Balance & Diversity"] = dim6;

    // Calculate total score
    let totalScore = 0;
    for (const key in report.dimensions) {
      totalScore += report.dimensions[key].score;
      if (report.dimensions[key].errors) {
        report.errors.push(...report.dimensions[key].errors);
      }
      if (report.dimensions[key].warnings) {
        report.warnings.push(...report.dimensions[key].warnings);
      }
    }

    report.score = Math.max(0, Math.min(100, Math.round(totalScore)));

    // Assign letter grade
    if (report.score >= 95) report.grade = "A+";
    else if (report.score >= 90) report.grade = "A";
    else if (report.score >= 80) report.grade = "B";
    else if (report.score >= 70) report.grade = "C";
    else report.grade = "F";

    return report;
  }

  // --- Dimension 1: Structure & Schema (20 pts) ---
  evaluateStructure(config, questions) {
    let score = 20;
    const errors = [];
    const warnings = [];

    // Title checks (5 pts)
    if (!config.title || typeof config.title !== "string") {
      score -= 5;
      errors.push("Missing config.title property.");
    } else {
      const words = config.title.trim().split(/\s+/).length;
      if (words > 5) {
        score -= 3;
        warnings.push(`config.title is ${words} words long (must be short, 2-5 words).`);
      } else if (words < 2) {
        score -= 2;
        warnings.push(`config.title is only ${words} word long (recommended 2-5 words).`);
      }
    }

    // Deprecated subtitle check (5 pts)
    if (config.subtitle !== undefined) {
      score -= 6;
      errors.push("Deprecated 'subtitle' property found in config. Subtitle is deprecated and must be removed.");
    }

    // Category check (3 pts)
    if (!config.category) {
      score -= 3;
      warnings.push("Missing config.category property.");
    }

    // Category inside questions check (4 pts)
    let categoryInQuestionCount = 0;
    questions.forEach((q, idx) => {
      if (q.category !== undefined) {
        categoryInQuestionCount++;
      }
    });
    if (categoryInQuestionCount > 0) {
      score -= 5;
      errors.push(`Found 'category' property inside ${categoryInQuestionCount} individual questions. Category must strictly be in config only.`);
    }

    // Sequential ID check (3 pts)
    let nonSequential = false;
    questions.forEach((q, idx) => {
      if (q.id !== idx + 1) nonSequential = true;
    });
    if (nonSequential) {
      score -= 2;
      warnings.push("Question IDs are not sequential 1-indexed integers (1, 2, 3...).");
    }

    return { score: Math.max(0, score), max: 20, errors, warnings };
  }

  // --- Dimension 2: Time Pressure & Minimum Time Calibration (15 pts) ---
  evaluateTimePressure(config, questions, stats) {
    let score = 15;
    const errors = [];
    const warnings = [];

    let totalEstimated = 0;
    let missingEstimated = 0;
    let unrealisticTime = 0;
    let violationsOfFormula = 0;

    questions.forEach((q, idx) => {
      const qNum = idx + 1;
      const text = q.question || "";
      const wordCount = text.trim().split(/\s+/).filter(Boolean).length;
      const minReadingTime = Math.max(4, Math.ceil(wordCount / 3));

      let optCount = 4;
      if (Array.isArray(q.options)) optCount = q.options.length;
      else if (Array.isArray(q.statements)) optCount = q.statements.length;

      // Formula: reading stem time + (2s * option count)
      const minFormulaTime = minReadingTime + (optCount * 2);

      if (typeof q.estimatedTime !== "number" || q.estimatedTime <= 0) {
        missingEstimated++;
      } else {
        totalEstimated += q.estimatedTime;
        if (q.estimatedTime < 5 || q.estimatedTime > 180) {
          unrealisticTime++;
        }
        // Check if estimated time satisfies reading time + 2s/option
        if (q.estimatedTime < minFormulaTime - 3) {
          violationsOfFormula++;
        }
      }
    });

    stats.avgEstimatedTime = questions.length > 0
      ? Math.round(totalEstimated / (questions.length - missingEstimated || 1))
      : 0;

    if (missingEstimated > 0) {
      const penalty = Math.min(10, missingEstimated * 5);
      score -= penalty;
      warnings.push(`${missingEstimated} questions missing 'estimatedTime' (required integer for Time Pressure).`);
    }

    if (violationsOfFormula > 0) {
      const penalty = Math.min(5, violationsOfFormula);
      score -= penalty;
      warnings.push(`${violationsOfFormula} questions have estimatedTime lower than the minimum reading speed + 2s/option baseline.`);
    }

    if (unrealisticTime > 0) {
      score -= 3;
      warnings.push(`${unrealisticTime} questions have unrealistic estimated times (<5s or >180s).`);
    }

    return { score: Math.max(0, score), max: 15, errors, warnings };
  }

  // --- Dimension 3: Distractor Quality & Option Length Parity (20 pts) ---
  evaluateDistractors(questions, stats) {
    let score = 20;
    const errors = [];
    const warnings = [];

    let longestCorrectCount = 0;
    let choiceQuestionsCount = 0;
    let duplicateOptionsCount = 0;

    questions.forEach((q, idx) => {
      const qNum = idx + 1;
      if (q.type === "single" || q.type === "multiple" || (!q.type && q.options)) {
        if (!Array.isArray(q.options) || q.options.length < 2) {
          errors.push(`Q${qNum}: Multiple choice question has fewer than 2 options.`);
          score -= 5;
          return;
        }

        // Duplicate options check
        const uniqueSet = new Set(q.options.map(o => String(o).trim().toLowerCase()));
        if (uniqueSet.size < q.options.length) {
          duplicateOptionsCount++;
          errors.push(`Q${qNum}: Contains duplicate options!`);
        }

        // Longest option bias check
        if (q.type === "single" && typeof q.correct === "number") {
          choiceQuestionsCount++;
          const lengths = q.options.map(o => String(o).length);
          const correctLen = lengths[q.correct] || 0;
          const maxLen = Math.max(...lengths);

          // If correct answer is strictly the longest option
          if (correctLen === maxLen && lengths.filter(l => l === maxLen).length === 1) {
            longestCorrectCount++;
          }
        }
      }
    });

    if (duplicateOptionsCount > 0) {
      score -= Math.min(10, duplicateOptionsCount * 5);
    }

    // Longest Option Bias Test: if correct answer is the longest option in > 50% of questions
    if (choiceQuestionsCount >= 3) {
      const longestRate = Math.round((longestCorrectCount / choiceQuestionsCount) * 100);
      stats.longestOptionBiasRate = longestRate;

      if (longestRate > 65) {
        score -= 8;
        errors.push(`High Longest-Option Bias detected (${longestRate}% of correct answers are the longest option). Distractors must have comparable detail and length.`);
      } else if (longestRate > 50) {
        score -= 4;
        warnings.push(`Moderate Longest-Option Bias (${longestRate}% of correct answers are longest). Ensure distractors match correct answer length.`);
      }
    }

    return { score: Math.max(0, score), max: 20, errors, warnings };
  }

  // --- Dimension 4: Pedagogical Independence & Zero-Errata (20 pts) ---
  evaluatePedagogyAndErrata(questions) {
    let score = 20;
    const errors = [];
    const warnings = [];

    // Forbidden meta-references to source materials / slides
    const slidePatterns = [
      /\btheo\s+slide\b/i,
      /\btrong\s+slide\b/i,
      /\bslide\s+\d+\b/i,
      /\bdựa\s+vào\s+slide\b/i,
      /\bnhư\s+đã\s+học\s+trong\s+slide\b/i,
      /\bdựa\s+vào\s+ví\s+dụ\s+trong\s+slide\b/i,
      /\bas\s+shown\s+in\s+slide\b/i,
      /\bin\s+the\s+lecture\s+notes\b/i,
      /\baccording\s+to\s+slide\b/i,
      /\bfrom\s+slide\b/i
    ];

    // Forbidden errata disclaimers in explanations
    const errataPatterns = [
      /\bđề\s+bài\s+bị\s+nhầm\b/i,
      /\blưu\s+ý:\s*đề\s+bài\s+(?:sai|nhầm)\b/i,
      /\bthực\s+chất\s+câu\s+hỏi\s+chưa\s+chuẩn\b/i,
      /\bcorrection:\s*(?:typo|the\s+question)\b/i,
      /\berratum\b/i,
      /\berrata\b/i,
      /\bđáp\s+án\s+thực\s+tế\s+phải\s+là\b/i
    ];

    questions.forEach((q, idx) => {
      const qNum = idx + 1;
      const questionText = q.question || "";
      const explanationText = q.explanation || "";

      // Check slide meta-references
      for (const pattern of slidePatterns) {
        if (pattern.test(questionText)) {
          score -= 8;
          errors.push(`Q${qNum}: Violates Self-Contained directive (contains meta-reference to slides: "${questionText.match(pattern)[0]}"). Questions must be self-contained.`);
          break;
        }
      }

      // Check zero-errata directive in explanation
      for (const pattern of errataPatterns) {
        if (pattern.test(explanationText)) {
          score -= 8;
          errors.push(`Q${qNum}: Violates Strict Zero-Errata directive (explanation contains errata note: "${explanationText.match(pattern)[0]}"). The question stem/options must be fixed directly, never apologized for in explanations.`);
          break;
        }
      }
    });

    return { score: Math.max(0, score), max: 20, errors, warnings };
  }

  // --- Dimension 5: Explanation Depth & LaTeX Formatting (15 pts) ---
  evaluateExplanationsAndMath(questions) {
    let score = 15;
    const errors = [];
    const warnings = [];

    questions.forEach((q, idx) => {
      const qNum = idx + 1;
      const expl = q.explanation || "";

      // Explanation completeness check (8 pts)
      if (!expl || expl.trim().length === 0) {
        score -= 3;
        errors.push(`Q${qNum}: Missing explanation.`);
      } else if (expl.trim().length < 25) {
        score -= 1;
        warnings.push(`Q${qNum}: Explanation is very short (${expl.trim().length} chars). Should provide pedagogical rationale.`);
      }

      // LaTeX delimiter balance check (4 pts)
      const combined = `${q.question || ""} ${expl} ${(q.options || []).join(" ")}`;
      // Check display math $$
      const displayMathMatches = combined.match(/\$\$/g) || [];
      if (displayMathMatches.length % 2 !== 0) {
        score -= 2;
        errors.push(`Q${qNum}: Unbalanced display math delimiters ($$). Found odd number (${displayMathMatches.length}).`);
      }

      // Check inline math $ (excluding escaped \$)
      const nonEscapedDollar = combined.replace(/\\\$/g, "").match(/\$/g) || [];
      if (nonEscapedDollar.length % 2 !== 0) {
        score -= 1;
        warnings.push(`Q${qNum}: Possibly unbalanced inline math delimiters ($).`);
      }

      // Raw HTML check (3 pts)
      if (/<(?:div|span\s+style|script|iframe|button)[^>]*>/i.test(combined)) {
        score -= 2;
        warnings.push(`Q${qNum}: Contains raw HTML tags. Only Markdown and KaTeX math are allowed.`);
      }
    });

    return { score: Math.max(0, score), max: 15, errors, warnings };
  }

  // --- Dimension 6: Balance & Answer Distribution (10 pts) ---
  evaluateBalanceAndDistribution(questions, stats) {
    let score = 10;
    const warnings = [];
    const errors = [];

    const singleChoiceQuestions = questions.filter(q => q.type === "single" || (!q.type && q.options && !Array.isArray(q.correct)));
    const keyDistribution = {};

    singleChoiceQuestions.forEach((q, idx) => {
      const qNum = idx + 1;
      // 4 choices standard check
      if (q.options && q.options.length !== 4) {
        warnings.push(`Q${qNum}: Single-choice question has ${q.options.length} options (Default standard is exactly 4 choices A, B, C, D).`);
      }

      if (typeof q.correct === "number") {
        keyDistribution[q.correct] = (keyDistribution[q.correct] || 0) + 1;
      }
    });

    // Answer key distribution check (avoid all answers being option 0)
    if (singleChoiceQuestions.length >= 4) {
      const totalSingle = singleChoiceQuestions.length;
      for (const pos in keyDistribution) {
        const pct = (keyDistribution[pos] / totalSingle) * 100;
        if (pct > 65) {
          score -= 3;
          warnings.push(`Answer key bias: Option index ${pos} is correct in ${Math.round(pct)}% of questions. Answers should be shuffled across choices.`);
          break;
        }
      }
    }

    return { score: Math.max(0, score), max: 10, errors, warnings };
  }

  /**
   * Format full visual CLI report
   */
  printReport(report, quizName = "Evaluated Quiz") {
    console.log("\n" + "=".repeat(70));
    console.log(`🏆 QUIZFRAMEWORK QUALITY BENCHMARK REPORT: ${quizName}`);
    console.log("=".repeat(70));

    console.log(`\nOverall Quality Score: ${report.score} / 100 [Grade: ${report.grade}]`);
    console.log(`Status: ${report.grade === "A+" || report.grade === "A" ? "✅ PASSED (Production Ready)" : report.grade === "B" ? "🟡 GOOD (Minor Tuning)" : "❌ FAILED (Prompt Re-run Recommended)"}\n`);

    console.log("Dimension Breakdown:");
    console.log("-".repeat(70));
    for (const [name, dim] of Object.entries(report.dimensions)) {
      const pct = Math.round((dim.score / dim.max) * 100);
      const barFilled = Math.round(pct / 10);
      const bar = "█".repeat(barFilled) + "░".repeat(10 - barFilled);
      console.log(`  ${name.padEnd(30)} [${bar}] ${dim.score}/${dim.max} pts (${pct}%)`);
    }

    if (report.stats) {
      console.log("\nStatistics:");
      console.log("-".repeat(70));
      console.log(`  Total Questions:          ${report.stats.totalQuestions}`);
      console.log(`  Avg Estimated Time:       ${report.stats.avgEstimatedTime} seconds/question`);
      if (report.stats.longestOptionBiasRate !== undefined) {
        console.log(`  Longest-Option Rate:      ${report.stats.longestOptionBiasRate}% (Target: <= 35%)`);
      }
    }

    if (report.errors.length > 0) {
      console.log("\n❌ Critical Violations & Errors:");
      console.log("-".repeat(70));
      report.errors.forEach(e => console.log(`  • ${e}`));
    }

    if (report.warnings.length > 0) {
      console.log("\n⚠️ Quality Warnings & Calibration Notes:");
      console.log("-".repeat(70));
      report.warnings.forEach(w => console.log(`  • ${w}`));
    }

    console.log("\n" + "=".repeat(70) + "\n");
  }
}

// CLI Execution & Self-Test Mode
if (require.main === module) {
  const benchmark = new QuizBenchmark();
  const args = process.argv.slice(2);

  if (args.length > 0) {
    const targetFile = path.resolve(args[0]);
    if (!fs.existsSync(targetFile)) {
      console.error(`File not found: ${targetFile}`);
      process.exit(1);
    }
    const content = fs.readFileSync(targetFile, "utf-8");
    const data = benchmark.parseQuizData(content);
    const report = benchmark.evaluate(data);
    benchmark.printReport(report, path.basename(targetFile));
  } else {
    console.log("🚀 Running QuizFramework Benchmark Suite on built-in datasets...\n");

    const baseDir = path.resolve(__dirname, "..");

    // 1. Evaluate quiz-data.js
    const quizDataPath = path.join(baseDir, "js/quiz-data.js");
    if (fs.existsSync(quizDataPath)) {
      const content = fs.readFileSync(quizDataPath, "utf-8");
      const data = benchmark.parseQuizData(content);
      const report = benchmark.evaluate(data);
      benchmark.printReport(report, "js/quiz-data.js");
    }

    // 2. Evaluate sample-economics-data.js
    const samplePath = path.join(baseDir, "js/sample-economics-data.js");
    if (fs.existsSync(samplePath)) {
      const content = fs.readFileSync(samplePath, "utf-8");
      const data = benchmark.parseQuizData(content);
      const report = benchmark.evaluate(data);
      benchmark.printReport(report, "js/sample-economics-data.js");
    }

    // 3. Test detection capability against an intentionally flawed quiz
    console.log("🧪 Testing Benchmark Detection Capability on Flawed Model Output...");
    const flawedQuiz = {
      config: {
        title: "This Title Has Too Many Words And Should Be Flagged",
        subtitle: "Deprecated Subtitle Should Fail",
        category: "Test"
      },
      questions: [
        {
          id: 1,
          category: "Should not be here",
          type: "single",
          question: "Theo slide 14, what is $P$ when supply increases?",
          options: [
            "This correct option is intentionally written to be vastly longer and more detailed than all the other options combined to trigger longest-option bias",
            "Short",
            "Short",
            "Short"
          ],
          correct: 0,
          explanation: "Lưu ý: đề bài bị nhầm lẫn nên ta sửa lại."
        }
      ]
    };

    const flawedReport = benchmark.evaluate(flawedQuiz);
    console.log(`  Flawed Quiz Score: ${flawedReport.score}/100 (Grade: ${flawedReport.grade})`);
    console.log(`  Errors detected: ${flawedReport.errors.length} (Expected >= 3 errors)`);
    if (flawedReport.errors.length >= 3 && flawedReport.score < 70) {
      console.log("  ✓ Benchmark successfully flagged all pedagogical, errata, and schema flaws!\n");
    } else {
      console.error("  ✗ Benchmark failed to catch flaws properly!");
      process.exit(1);
    }
  }
}

module.exports = { QuizBenchmark };
